function autoSuggestCompanyName(searchKeyword, type, offset, limit, searchType, typeOfCompany) {
    const $eleSuggestionList = $(".suggestionsList");
    $eleSuggestionList.html("");
    $eleSuggestionList.show();
    callCompanySearch(searchKeyword, type, offset, limit, searchType, typeOfCompany);
}

function callCompanySearch(searchKeyword, type, offset, limit, searchType, typeOfCompany) {
    const $eleAutoCompleteSuggestion = $(".autocompletesuggestion .autoComplete .guideFieldError"),
        $elePageLoader = $("#loadingPage");
    $elePageLoader.addClass("guideServiceLoading");
    var data = "type=" + type + "&offset=" + offset + "&limit=" + limit +
        "&searchType=" + searchType + "&typeOfCompany=" + typeOfCompany +  "&searchKeyword=" + searchKeyword;
    var result = "";
    $.ajax({
        url: "/bin/mca/companySearch",
        type: "GET",
        data: "data=" + encrypt(data),
        async: false,
        success: function(response) {
            if (response.resCode === "200") {
                $eleAutoCompleteSuggestion.css("visibility", "hidden");
                $eleAutoCompleteSuggestion.text("");
                result = response;
                var count = response.data.count < limit ? response.data.count : limit;
                if (count > 0) {
                    var results = JSON.parse(response.data).result;
                    for (var i = 0; i < count && i < results.length; i++) {
						var companyData = encrypt(JSON.stringify(results[i]));
						var listItem1 = encrypt("<li>");
		                var listItem2 = encrypt("</li>");
						var space = " - ";
						$(".suggestionsList").append(
						 `${decrypt(decodeURIComponent(listItem1))}
							${JSON.parse(decrypt(decodeURIComponent(companyData))).companyName}
							${space}
							${JSON.parse(decrypt(decodeURIComponent(companyData))).CIN}
							${decrypt(decodeURIComponent(listItem2))}`
                        );

                    }

                } else {
                     $("#noResultFoundModal").modal('show');
                    $eleAutoCompleteSuggestion.css("visibility", "visible");
                    $eleAutoCompleteSuggestion.text("No results found");
                }
            } else {

            }
            $elePageLoader.removeClass("guideServiceLoading");
        },
        error: function(response) {
            $elePageLoader.removeClass("guideServiceLoading");
            $eleAutoCompleteSuggestion.css("visibility", "visible");
            $eleAutoCompleteSuggestion.text("There is an issue with service");
        }

    });

    return result;
}
function createCompanyTable(tableName, searchKeyword, type, offset, limit, searchType, typeOfCompany, showTable) {

    var reqData =  "type=" + type + "&offset=" + offset + "&limit=" + limit +
        "&searchType=" + searchType + "&typeOfCompany=" + typeOfCompany + "&searchKeyword=" + searchKeyword;
    try {

        $('.' + tableName).DataTable({
            "searching": true,
            "paging": true,
            "dom": 'rtp',
            "searchHighlight": true,
            "stateSave" : true,
            "pagingType": "numbers",
            "pageLength": 10,
            "destroy": true,
            ajax: function(data, callback, settings) {
                $.ajax({
                    url: '/bin/mca/companySearch',
                    cache: false,
                    type: 'GET',
                    data: "data=" + encrypt(reqData),
                    success: function(data2, textStatus, jQxhr) {
                        if(data2.resCode != "200"){
							$("#noResultFoundModal").modal('show');
                            return;
                        }
                        var respData = JSON.parse(data2.data);
                        $(".companyNameModalContainer .searchResultCount #searchCount").text(respData.count);
                        $(".companyNameModalContainer .searchResultCount #searchItem").text($(".companySearchBox input[type='text']").val());
						respData.result =  respData.result.sort( function( a, b ) {
                            if(a.companyName && b.companyName){
    							return a.companyName < b.companyName ? -1 : a.companyName > b.companyName ? 1 : 0;
                            } else{
                                return 0;
                            }
						});
                        callback({
                            data: respData.result,
                            recordsTotal: respData.count,
                            recordsFiltered: respData.count
                        });
                        if(respData.count >0 ) {
							$("#companyNameModalContainer").modal('show');
                        } else{
				        	$("#noResultFoundModal").modal('show');
                        }
                    },
                    error: function(jqXhr, textStatus, errorThrown) {
                       console.error("error", errorThrown);
                    }
                });
            },
            "serverSide": true,
            columns: [{
                    data: "companyName"
                },
                {
                    data: "CIN"
                }
            ],
            "initComplete": function(settings, json) {

				var term = $('.companySearchBox input').val();
				
				 var $cells = $('table.companyNameCustomTable tr td.sorting_1');
                 $cells.each(function(i, v) {
                    var results = $(v).text();
                    results = results.replace(new RegExp(term, "gi"), "<mark class='search-matches'>$&</mark>");
                    $(v).html(results);

                })
                      $(".companyNameCustomTable").DataTable().page( offset/10 ).draw( 'page' );

            }

        });
    } catch (e) { console.error(e.message); }
}

function validateTotalFormAttachmentSize() {
    var formAttachment = sessionStorage.getItem("fileAttachmentArr");
    if (formAttachment === null || formAttachment === undefined) {
        return true;
    } else {
        formAttachment = JSON.parse(formAttachment);
        var totalsize = 0 * 1;
        for (var i = 0; i < formAttachment.length; ++i) {

            if (formAttachment[i].attachmentCategory === "Attachment") {
                totalsize = totalsize + parseFloat(formAttachment[i].activityFileSize);
            }
        }
        if (totalsize > (10 * 1024 * 1024)) {
			var fileModal = $("#fileattachmenterror-action-modal");
            fileModal.modal('show');
            return false;
        }
        return true;
    }
}



function setDMSFolder(formAttachment) {
    sessionStorage.removeItem("folderpath");
    sessionStorage.removeItem("dmsfolder");
    if (formAttachment !== undefined && formAttachment !== null && formAttachment.length !== 0) {
        var attachmentdata = JSON.stringify(formAttachment);
        sessionStorage.setItem("fileAttachmentArr", attachmentdata);
    }

    var fileAttachments = sessionStorage.getItem("fileAttachmentArr");
    if (fileAttachments !== null && fileAttachments !== undefined) {
        fileAttachments = JSON.parse(fileAttachments);
        var folderpath = fileAttachments[0].folderId;
        var foldername = fileAttachments[0].folderId;

        sessionStorage.setItem("folderpath", folderpath);
        sessionStorage.setItem("dmsfolder", foldername);
    }
}
//Created this function as due to form reset implemented we were not able to call CIN code form applicaiton history and date of incorporation check was missing for certain firlds so had to introduce this function
function prefillOnlySpecificDataWithCIN(cinVal) {

    guideBridge.resolveNode("savedCinVal").value = cinVal;
    var CIN_ = cinVal;
    const form = new FormData();
    var dataStr = '{"CIN":"' + cinVal + '"}';
    form.append("data", encrypt(dataStr));
    form.append("endpointID", "inc12-withoutassociation");
    form.append("csrfToken", encrypt(fnGetCSRFToken()));
    form.append("csrfDecode", false);
    const settings = {
        "async": true,
        "crossDomain": true,
        "url": "/bin/commongetapi",
        "method": "POST",
        "headers": {},
        "processData": false,
        "contentType": false,
        "mimeType": "multipart/form-data",
        "data": form
    };
    $.ajax(settings).done(function(response) {
        if (typeof(response) == 'string') {
            var JSONData = JSON.parse(response);
            JSONData = JSON.parse(JSONData.resStr);
        } else {
            var JSONData = JSON.parse(response.resStr);
        }
        if (JSONData.error === "" && JSONData.message.toLowerCase() === "data fetched successfully" && (JSONData.data[0].companyInfo.companyStatus == 'Active' || JSONData.data[0].companyInfo.companyStatus == 'Under CIRP' || JSONData.data[0].companyInfo.companyStatus == 'Under Liquidation')) {

            sessionStorage.dateOfIncorporation = JSONData.data[0].companyInfo.dateOfIncorporation;
            sessionStorage.companyOrigin = JSONData.data[0].companyInfo.companyOrigin ? JSONData.data[0].companyInfo.companyOrigin : "";
            sessionStorage.companyStatus = JSONData.data[0].companyInfo.companyStatus ? JSONData.data[0].companyInfo.companyStatus : "";
            sessionStorage.companyType = JSONData.data[0].companyInfo.companyType ? JSONData.data[0].companyInfo.companyType : "";
            sessionStorage.classOfCompany = JSONData.data[0].companyInfo.classOfCompany ? JSONData.data[0].companyInfo.classOfCompany : "";
            guideBridge.resolveNode("classOfCompany").value = JSONData.data[0].companyInfo.classOfCompany !== null ? JSONData.data[0].companyInfo.classOfCompany : "";
            sessionStorage.smallCompanyFlag = JSONData.data[0].companyInfo.smallCompanyFlag !== null ? JSONData.data[0].companyInfo.smallCompanyFlag : "";
            
            if (sessionStorage.classOfCompany !== "One Person Company" || sessionStorage.smallCompanyFlag == "Y") {
                guideBridge.resolveNode("categoryOfProfessional").mandatory = false;
                guideBridge.resolveNode("whetherAssociateOrFellow").mandatory = false;
            } else {
                guideBridge.resolveNode("categoryOfProfessional").mandatory = true;
                guideBridge.resolveNode("whetherAssociateOrFellow").mandatory = true;
            }
            if (guideBridge.resolveNode("classOfCompany").value == "Private" || guideBridge.resolveNode("classOfCompany").value == "Public") {
                guideBridge.resolveNode("DateOfBoard").mandatory = true;
                guideBridge.resolveNode("table2").Row1._instanceManager._instances[0].din.mandatory = true;
                guideBridge.resolveNode("table2").Row1._instanceManager._instances[0].name1.mandatory = true;
                guideBridge.resolveNode("table2").Row1._instanceManager._instances[0].designation1.mandatory = true;
                guideBridge.resolveNode("table2").Row1._instanceManager._instances[0].DateOfSigningOfBoard.mandatory = true;
            } 
            else {
                guideBridge.resolveNode("DateOfBoard").mandatory = false;
                guideBridge.resolveNode("table2").Row1._instanceManager._instances[0].din.mandatory = false;
                guideBridge.resolveNode("table2").Row1._instanceManager._instances[0].name1.mandatory = false;
                guideBridge.resolveNode("table2").Row1._instanceManager._instances[0].designation1.mandatory = false;
                guideBridge.resolveNode("table2").Row1._instanceManager._instances[0].DateOfSigningOfBoard.mandatory = false;
            }
            sessionStorage.shareCapitalFlag = JSONData.data[0].companyInfo.shareCapitalFlag;
            if (sessionStorage.shareCapitalFlag !== "Y") {
                mgt7Table(false);
                guideBridge.resolveNode("table1643979926231").resetData();
            } 
            else if (sessionStorage.shareCapitalFlag == "Y") {
                mgt7TableEnabled(true);
            }
            if (formStage == 1) {
                guideBridge.resolveNode("panel5AOC4").enabled = true;
                guideBridge.resolveNode("panel6AOC4").enabled = true;
                guideBridge.resolveNode("panel5AOC4").enabled = false;
                guideBridge.resolveNode("panel6AOC4").enabled = false;
            }
            
        }
    });
}
function removeAttachment(labelName){
    try {
        var filemetadadata = fetchfilemetadata();
        var newAttachment = [];

        if (filemetadadata.length > 0) {
            for (var j = 0; j < filemetadadata.length; j++) {
                if (Object.keys(filemetadadata[j]).length !== 0) {
                    
                    if(filemetadadata[j].attachmentLabel != labelName)
                        newAttachment.push(filemetadadata[j]);
                    
                }
            }
            sessionStorage.fileAttachmentArr = JSON.stringify(newAttachment);
        }
    } catch (err) {
        console.error(err);
    }
}
