function compareNumbers(value1, value2) {
    var valueX = parseFloat(value1);
    if(value1 === null || value1 === "")
        return true;
    if(value2 === null || value2 === "")
        return true;
    var valueX = parseFloat(value1);
    var valueY = parseFloat(value2);
    if(valueX == 0 && valueY == 0)
        return true;
    value1 = String(value1);
    value2 = String(value2);
    var decimalSeparator = '.'; // Assuming decimal separator is a period (.)
    
    // Split the values into integral and decimal parts
    var[intPart1, decPart1 = ""] = value1.split(decimalSeparator);
    var[intPart2, decPart2 = ""] = value2.split(decimalSeparator);
    
    // Compare the integral parts
    if (intPart1.length > intPart2.length) {
        return false;
    } else if (intPart2.length > intPart1.length) {
        return true;
    } else {
        if (intPart1 > intPart2) {
            return false;
        } else if (intPart2 > intPart1) {
            return true;
        }
    }
    
    // Compare the decimal parts
    var maxDecLength = Math.max(decPart1.length, decPart2.length);
    
    // Pad the decimal parts with zeros to ensure equal lengths
    decPart1 = decPart1.padEnd(maxDecLength, '0');
    decPart2 = decPart2.padEnd(maxDecLength, '0');
    
    if (decPart1 > decPart2) {
        return false;
    } else if (decPart2 > decPart1) {
        return true;
    }

    return true; // If both integral and decimal parts are equal
}

