function fnGetCSRFToken() {
    const tokenElement = window.parent.document.querySelector("#csrfToken");
    return tokenElement && tokenElement.value ? tokenElement.value : "";
}

function callAllLinkedSRNFunction() {
    if (guideBridge.resolveNode("applicationHistoryExecuting").isEmpty()) {
        try {
            formDateFetch();
        } catch (e) {
            console.error("issue in form Date fetch", e);
        }
	}
        try {
            formDpt3Fetch();
        } catch (e) {
            console.error(e);
        }
    
}
function formDateFetch() {
    if (!guideBridge.resolveNode("fromDate").isEmpty() && !guideBridge.resolveNode("toDate").isEmpty()) {
        guideBridge.resolveNode("srnPrevious").resetData();
        var cinValue = "";
        if (guideBridge.resolveNode("userTypeHidden").value == "Company") {
            cinValue = guideBridge.resolveNode("CINofCompany").value;
        } else if ((ssUserInfoMd5 && isProfessionalUserRole(JSON.parse(sessionStorage.getItem(ssUserInfoMd5)).userRole))) {
            cinValue = guideBridge.resolveNode("CIN_Number_Professional_User").value;
        } else {
            cinValue = guideBridge.resolveNode("CIN_Number_Other_User").value;
        }
        var startDate = new Date(guideBridge.resolveNode("fromDate").value);
        startDate.setFullYear(startDate.getFullYear() - 1);
        startDate = (startDate.getMonth() + 1).toString().padStart(2, "0") + "/" + startDate.getDate().toString().padStart(2, "0") + "/" + startDate.getFullYear();
        var endDate = new Date(guideBridge.resolveNode("fromDate").value);
        endDate = endDate.subDays(1);
        endDate = (endDate.getMonth() + 1).toString().padStart(2, "0") + "/" + endDate.getDate().toString().padStart(2, "0") + "/" + endDate.getFullYear();
        
        if (cinValue !== "") {
            formDateFetchFunc(cinValue, startDate, endDate);
        }
    }
}
Date.prototype.subDays = function (days) {
    var date = new Date(this.valueOf());
    date.setDate(date.getDate() - days);
    return date;
};
function formDateFetchFunc(cinValue, startDate, endDate) {
    
    var data1 = {
        value: startDate
    };
    var data2 = {
        value: endDate
    };
    
    try {
        const form = new FormData();
        
        //form.append("data", "{\"CIN\":\"" + cinValue + "\",\"FORMTYPE\":\"AOC-4\",\"FYFROMDATE\":\"" + data1.value + "\",\"FYTODATE\":\"" + data2.value + "\"}");
        var dataStr = "{\"CIN\":\"" + cinValue + "\",\"FORMTYPE\":\"AOC-4\",\"FYFROMDATE\":\"" + data1.value + "\",\"FYTODATE\":\"" + data2.value + "\"}";
        form.append("data", encrypt(dataStr));
        form.append("endpointID", "fetchAOC4SRN");
        form.append("csrfToken", encrypt(fnGetCSRFToken()));
		form.append("csrfDecode", false);
        //form.append("method", "post");

        const settings = {
            "async": false,
            "crossDomain": true,
            "url": "/bin/commongetapi",
            "method": "POST",
            "headers": {},
            
            "processData": false,
            "contentType": false,
            "mimeType": "multipart/form-data",
            "data": form
        };
        $.ajax(settings).done(function (response) {
            try {
                var JSONData = JSON.parse(response);
                var response = JSON.parse(JSONData.resStr);
                
                if (response.message.toLowerCase() == "data fetched successfully") {
                    var data = response.data;
                    var date1 = "";
                    var initSRN = "";
                    try {
                        if (data[0].srnStatus == "Approved" || data[0].srnStatus == "Registered") {
                            date1 = new Date(data[0].approvedDate);
                            initSRN = data[0].SRN;
                            
                        }
                        
                        for (var i = 1; i < data.length; i++) {
                            if (data[i].srnStatus == "Approved" || data[i].srnStatus == "Registered") {
                                if (new Date(data[i].approvedDate) > date1 && data[i].SRN != "") {
                                    date1 = new Date(data[i].approvedDate);
                                    initSRN = data[i].SRN;
                                }
                            }
                        }
                    } catch (e) {
                        console.error(e);
                    }
                    guideBridge.resolveNode("srnPrevious").value = initSRN;
                }
                
            } catch (e) {
                console.error("error in form date fetch api " + e);
            }
            
        });
    } catch (e) {
        console.error("Error in prefilling the data", e);
    }
}
function formDpt3Fetch() {
    if (!guideBridge.resolveNode("fromDate").isEmpty() && !guideBridge.resolveNode("toDate").isEmpty()) {
        guideBridge.resolveNode("dpt3srnPrevious").resetData();
        guideBridge.resolveNode("dpt3Field12").resetData();
        guideBridge.resolveNode("dpt3Field10").resetData();
        guideBridge.resolveNode("dpt3Edir").resetData();
        guideBridge.resolveNode("dpt3Field9").resetData();
        sessionStorage.removeItem('dpt3Edir');

        var cinValue = "";
        if (guideBridge.resolveNode("userTypeHidden").value == "Company") {
            cinValue = guideBridge.resolveNode("CINofCompany").value;
        } else if (guideBridge.resolveNode("userTypeHidden").value == "Professional") {
            cinValue = guideBridge.resolveNode("CIN_Number_Professional_User").value;
        } else {
            cinValue = guideBridge.resolveNode("CIN_Number_Other_User").value;
        }
        var startDate = (guideBridge.resolveNode("fromDate").value).replace(/(\d{4})-(\d\d)-(\d\d)/, "$2/$3/$1");
        var endDate = (guideBridge.resolveNode("toDate").value).replace(/(\d{4})-(\d\d)-(\d\d)/, "$2/$3/$1");
        
        if (cinValue !== "") {
            testOne(cinValue, startDate, endDate);
        }
    }
}
function testOne(cinValue, startDate, endDate) {
    
    var data1 = {
        value: startDate
    };
    var data2 = {
        value: endDate
    };
    
    try {
        const form = new FormData();
        
        //form.append("data", "{\"CIN\":\"" + cinValue + "\",\"SRType\":\"DPT-3\",\"FYFROMDATE\":\"" + data1.value + "\",\"FYTODATE\":\"" + data2.value + "\"}");
        var dataStr = "{\"CIN\":\"" + cinValue + "\",\"SRType\":\"DPT-3\",\"FYFROMDATE\":\"" + data1.value + "\",\"FYTODATE\":\"" + data2.value + "\"}";
        form.append("data", encrypt(dataStr));
        form.append("endpointID", "dpt3FetchSrn");
        form.append("csrfToken", encrypt(fnGetCSRFToken()));
		form.append("csrfDecode", false);
        //form.append("method", "post");
        
        const settings = {
            "async": false,
            "crossDomain": true,
            "url": "/bin/commongetapi",
            "method": "POST",
            "headers": {},
            
            "processData": false,
            "contentType": false,
            "mimeType": "multipart/form-data",
            "data": form
        };
        $.ajax(settings).done(function (response) {
            try {
                var JSONData = JSON.parse(response);
                response = JSON.parse(JSONData.resStr);
                
                //  var response = JSON.parse(outputData);
                if (response.message.toLowerCase() == "data fetched successfully") {
                    var data = response.data;
                    
                    var oldSRN = data[0].SRN;
                    guideBridge.resolveNode("dpt3srnPrevious").value = oldSRN;
                    getOnloadDetails(oldSRN);
                    
                }
            } catch (e) {
                console.error("error in dpt3 fetch api " + e);
            }
            
        });
    } catch (e) {
        console.error("Error in prefilling the data", e);
    }
}
function getOnloadDetails(generatedSrn) {
    
    try {

        const form1 = new FormData();
         var dataStr = "{\n        \"requestBody\": {\n            \"srNumber\": \"" + generatedSrn + "\",\n            \"referenceNumber\": \"" + "" + "\"\n        }\n    }"
        form1.append("data", encrypt(dataStr));
        form1.append("endpointID", "onloadDpt3");
        form1.append("method", "post");
        form1.append("csrfToken", encrypt(fnGetCSRFToken()));
		form1.append("csrfDecode", false);
        const settings = {
            "async": false,
            "crossDomain": true,
            "url": "/bin/commongetapi",
            "method": "POST",
            "headers": {},
            "processData": false,
            "contentType": false,
            "mimeType": "multipart/form-data",
            "data": form1
        };
        $.ajax(settings).done(function (response) {
            try {
                var JSONData = JSON.parse(response);
                JSONData = JSON.parse(JSONData.resStr);
                var formData = JSONData.data.formData;
                if (formData !== "" && formData !== null) {
                    var field = +(formData.reneweddepositamtyear !== null ? formData.reneweddepositamtyear : "") + +(formData.secureddeposit !== null ? formData.secureddeposit : "") + +(formData.unsecureddeposit !== null ? formData.unsecureddeposit : "");
                    guideBridge.resolveNode("dpt3Field9").value = field;
                    guideBridge.resolveNode("dpt3Edir").value = +(formData.secureddeposit !== null ? formData.secureddeposit : "") + +(formData.unsecureddeposit !== null ? formData.unsecureddeposit : "");
                    guideBridge.resolveNode("dpt3Field10").value = formData.matureddepositamtclaimednotpaid !== null ? formData.matureddepositamtclaimednotpaid : "";
                    guideBridge.resolveNode("dpt3Field12").value = formData.matureddepositamtnotclaimed !== null ? formData.matureddepositamtnotclaimed : "";
                    sessionStorage.setItem("dpt3Edir",  guideBridge.resolveNode("dpt3Edir").value);

                }
            } catch (e) {
                console.error("error in dpt3 onload " + e);
            }
            
        });
    } catch (e) {
        console.error("Error in prefilling the data", e);
    }
}
